CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domains (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, enabled INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, pass_hash TEXT NOT NULL, salt TEXT NOT NULL, banned INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_active_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS users_last_active ON users(last_active_at);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS mailboxes (id INTEGER PRIMARY KEY AUTOINCREMENT, address TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, is_public INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_mail_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS mailboxes_user ON mailboxes(user_id);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, mailbox_id INTEGER NOT NULL REFERENCES mailboxes(id) ON DELETE CASCADE, msg_key TEXT NOT NULL, from_addr TEXT NOT NULL DEFAULT '', from_name TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL DEFAULT '', preview TEXT NOT NULL DEFAULT '', otp TEXT, text_body TEXT, html_body TEXT, size INTEGER NOT NULL DEFAULT 0, received_at INTEGER NOT NULL, UNIQUE(mailbox_id, msg_key));
CREATE INDEX IF NOT EXISTS messages_mailbox_time ON messages(mailbox_id, received_at DESC);
CREATE INDEX IF NOT EXISTS messages_time ON messages(received_at);
